  17	
  18	  for (const [kind, look] of Object.entries(palette)) {
  19	    const cnv = document.createElement('canvas');
  20	    cnv.width = sizePx; cnv.height = sizePx;
  21	    const fgCnv = document.createElement('canvas');
  22	    fgCnv.width = sizePx; fgCnv.height = sizePx;
  23	    const g = cnv.getContext('2d');
  24	    const fgCtx = fgCnv.getContext('2d');
  25	    renderLook(g, look, { sizePx, fontPx, glowLayers, includeBackground: true });
  26	    renderLook(fgCtx, look, { sizePx, fontPx, glowLayers, includeBackground: false });
