 312	        if (!style) continue;
 313	        const pulse = 0.5 + 0.5 * Math.sin(Number(fxTime || 0) * style.speed + (entity.id | 0) * 0.37);
 314	        const strength = Math.max(0.7, Math.min(1.4, Number(aura.strength || 1)));
 315	        const radius = style.radius * (0.92 + 0.10 * pulse) * strength;
 316	        const [r, g, b] = style.color;
